28	/// Data structure that holds the node with its formatted version
29	#[derive(Clone, Debug)]
30	pub(crate) enum ChainMember {
31	    /// Holds onto a [biome_js_syntax::JsStaticMemberExpression]
32	    StaticMember {
33	        expression: JsStaticMemberExpression,
34	    },
35	
36	    /// Holds onto a [biome_js_syntax::JsCallExpression]
37	    CallExpression {
38	        expression: JsCallExpression,
39	        position: CallExpressionPosition,
40	    },
41	
42	    /// Holds onto a [biome_js_syntax::JsComputedMemberExpression]
43	    ComputedMember {
44	        expression: JsComputedMemberExpression,
45	    },
46	
47	    TsNonNullAssertionExpression {
48	        expression: TsNonNullAssertionExpression,
49	    },
50	
51	    /// Any other node that are not  [biome_js_syntax::JsCallExpression] or [biome_js_syntax::JsStaticMemberExpression]
52	    /// Are tracked using this variant
53	    Node(JsSyntaxNode),
54	}
55	
56	impl ChainMember {
57	    /// checks if the current node is a [biome_js_syntax::JsCallExpression], or a [biome_js_syntax::JsImportExpression]
58	    pub fn is_call_like_expression(&self) -> bool {
59	        match self {
60	            ChainMember::CallExpression { .. } => true,
61	            ChainMember::Node(node) => {
62	                JsImportCallExpression::can_cast(node.kind())
63	                    | JsCallExpression::can_cast(node.kind())
64	            }
65	            _ => false,
66	        }
67	    }
68	
69	    pub(crate) const fn is_call_expression(&self) -> bool {
70	        matches!(self, ChainMember::CallExpression { .. })
71	    }
72	
73	    pub(crate) fn syntax(&self) -> &JsSyntaxNode {
74	        match self {
75	            ChainMember::StaticMember { expression, .. } => expression.syntax(),
76	            ChainMember::CallExpression { expression, .. } => expression.syntax(),
77	            ChainMember::ComputedMember { expression, .. } => expression.syntax(),
78	            ChainMember::TsNonNullAssertionExpression { expression } => expression.syntax(),
79	            ChainMember::Node(node) => node,
80	        }
81	    }
82	
83	    pub const fn is_computed_expression(&self) -> bool {
84	        matches!(self, ChainMember::ComputedMember { .. })
85	    }
86	
87	    pub(super) fn needs_empty_line_before(&self) -> bool {
88	        match self {
89	            ChainMember::StaticMember { expression } => {
90	                let operator = expression.operator_token();
91	
92	                match operator {
93	                    Ok(operator) => get_lines_before_token(&operator) > 1,
94	                    _ => false,
95	                }
96	            }
97	            ChainMember::ComputedMember { expression } => {
98	                let l_brack_token = expression.l_brack_token();
99	
100	                match l_brack_token {
101	                    Ok(l_brack_token) => {
102	                        get_lines_before_token(
103	                            &expression.optional_chain_token().unwrap_or(l_brack_token),
104	                        ) > 1
105	                    }
106	                    _ => false,
107	                }
108	            }
109	            _ => false,
110	        }
111	    }
112	}
113	
114	impl Format<JsFormatContext> for ChainMember {
115	    fn fmt(&self, f: &mut JsFormatter) -> FormatResult<()> {
116	        if self.needs_empty_line_before() {
117	            write!(f, [empty_line()])?;
118	        }
119	
120	        match self {
121	            ChainMember::StaticMember { expression } => {
122	                let JsStaticMemberExpressionFields {
123	                    // Formatted as part of the previous item
124	                    object: _,
125	                    operator_token,
126	                    member,
127	                } = expression.as_fields();
128	
129	                write!(
130	                    f,
131	                    [
132	                        format_leading_comments(expression.syntax()),
133	                        operator_token.format(),
134	                        member.format(),
135	                        format_trailing_comments(expression.syntax())
136	                    ]
137	                )
138	            }
139	
140	            ChainMember::TsNonNullAssertionExpression { expression } => {
141	                let TsNonNullAssertionExpressionFields {
142	                    expression: _,
143	                    excl_token,
144	                } = expression.as_fields();
145	
146	                write!(
147	                    f,
148	                    [
149	                        format_leading_comments(expression.syntax()),
150	                        excl_token.format(),
151	                        format_trailing_comments(expression.syntax())
152	                    ]
153	                )
154	            }
155	
156	            ChainMember::CallExpression {
157	                expression,
158	                position,
159	            } => {
160	                let JsCallExpressionFields {
161	                    // Formatted as part of the previous item
162	                    callee: _,
163	                    optional_chain_token,
164	                    type_arguments,
165	                    arguments,
166	                } = expression.as_fields();
167	
168	                match position {
169	                    CallExpressionPosition::Start => write!(f, [expression.format()]),
170	                    CallExpressionPosition::Middle => {
171	                        write!(
172	                            f,
173	                            [
174	                                format_leading_comments(expression.syntax()),
175	                                optional_chain_token.format(),
176	                                type_arguments.format(),
177	                                arguments.format(),
178	                                format_trailing_comments(expression.syntax())
179	                            ]
180	                        )
181	                    }
182	                    CallExpressionPosition::End => {
183	                        write!(
184	                            f,
185	                            [
186	                                optional_chain_token.format(),
187	                                type_arguments.format(),
188	                                arguments.format(),
189	                            ]
190	                        )
191	                    }
192	                }
193	            }
194	            ChainMember::ComputedMember { expression } => {
195	                write!(
196	                    f,
197	                    [
198	                        format_leading_comments(expression.syntax()),
199	                        FormatComputedMemberLookup::new(&expression.clone().into()),
200	                        format_trailing_comments(expression.syntax())
201	                    ]
202	                )
203	            }
204	            ChainMember::Node(node) => {
205	                write!(f, [node.format()])
206	            }
207	        }
208	    }
209	}
